import { readFileSync } from "node:fs";
import { resolve } from "node:path";

import { describe, expect, test } from "vitest";
import { Autumn } from "@useautumn/convex";

const expectedApiMethods = [
	"attach",
	"billingPortal",
	"cancel",
	"check",
	"checkout",
	"createCustomer",
	"createEntity",
	"createReferralCode",
	"getEntity",
	"aggregateEvents",
	"listProducts",
	"listEvents",
	"query",
	"redeemReferralCode",
	"setupPayment",
	"track",
	"usage",
].sort();

describe("upstream API contract", () => {
	test("Autumn.api() exposes the expected callable surface", () => {
		const autumn = new Autumn({} as never, {
			identify: async () => null,
			secretKey: "am_sk_test",
		});

		expect(Object.keys(autumn.api()).sort()).toEqual(expectedApiMethods);
	});

	test("local Convex export list stays in lockstep with upstream", () => {
		const source = readFileSync(
			resolve(process.cwd(), "src/lib/convex/autumn.ts"),
			"utf8",
		);
		const match = source.match(/export const\s*\{([^}]+)\}\s*=\s*autumn\.api\(\);/m);

		expect(match).toBeTruthy();

		const exportedMethods = match![1]
			.split(",")
			.map((value) => value.trim())
			.filter(Boolean)
			.sort();

		expect(exportedMethods).toEqual(expectedApiMethods);
	});
});

#!/usr/bin/env node

import { exportJWK, exportPKCS8, generateKeyPair } from 'jose';
import { execSync } from 'child_process';

console.log('🔑 Generating JWT keys for Convex Auth...');

// Generate keys
const keys = await generateKeyPair('RS256', {
	extractable: true
});

const privateKey = await exportPKCS8(keys.privateKey);
const publicKey = await exportJWK(keys.publicKey);
const jwks = JSON.stringify({ keys: [{ use: 'sig', ...publicKey }] });

// Format private key for environment variable (replace newlines with spaces)
const formattedPrivateKey = [REDACTED], ' ');

console.log('✅ Keys generated successfully');

try {
	console.log('🔧 Setting JWT_PRIVATE_KEY in Convex...');
	execSync(`bunx convex env set JWT_PRIVATE_KEY -- "${formattedPrivateKey}"`, {
		stdio: 'inherit'
	});

	console.log('🔧 Setting JWKS in Convex...');
	execSync(`bunx convex env set JWKS -- '${jwks}'`, {
		stdio: 'inherit'
	});

	console.log('🎉 Authentication keys configured successfully!');
	console.log('Your Convex Auth setup is now complete.');
} catch (error) {
	console.error('❌ Error setting environment variables:');
	console.error(error.message);
	console.log('\n📋 Manual setup fallback:');
	console.log(`JWT_PRIVATE_KEY="[REDACTED]}"`);
	console.log(`JWKS=${jwks}`);
	process.exit(1);
}

import type { Page } from "@playwright/test";

/**
 * Shared authentication helpers for e2e tests.
 */

const primarySecret =
	[REDACTED] ?? process.env.AUTH_E2E_TEST_SECRET;
const secondarySecret = [REDACTED];

function requireSecret(secret: string | undefined, label: string): string {
	if (!secret) {
		throw new Error(`Missing ${label} environment variable for E2E auth.`);
	}

	return secret;
}

/**
 * Sign in with the test user.
 *
 * @param page - The Playwright page instance.
 */
export async function signIn(page: Page, secret = [REDACTED], "AUTH_E2E_TEST_SECRET_PRIMARY")): Promise<void> {
	await page.goto("/signin");
	await page.getByLabel("Secret").fill(secret);
	await page.getByRole("button").getByText("Sign in with secret").click();
	await page.waitForURL("/product");
}

export async function signInAsPrimary(page: Page): Promise<void> {
	await signIn(page, requireSecret(primarySecret, "AUTH_E2E_TEST_SECRET_PRIMARY"));
}

export async function signInAsSecondary(page: Page): Promise<void> {
	await signIn(page, requireSecret(secondarySecret, "AUTH_E2E_TEST_SECRET_SECONDARY"));
}

/**
 * Sign out the current user.
 *
 * @param page - The Playwright page instance.
 */
export async function signOut(page: Page): Promise<void> {
	await page.context().clearCookies();
	try {
		await page.evaluate(() => {
			try {
				localStorage.clear();
				sessionStorage.clear();
			} catch {
				// storage may be inaccessible before any navigation; ignore
			}
		});
	} catch {
		// no document yet (fresh context) — nothing to clear
	}
	await page.goto("/", { waitUntil: "networkidle" });
}

/**
 * Navigate to the account page, handling authentication if required.
 *
 * @param page - The Playwright page instance.
 */
export async function navigateToAccount(page: Page): Promise<void> {
	await page.goto("/account");

	if (page.url().includes("/signin")) {
		await signIn(page);
		await page.goto("/account");
	}

	await page.waitForURL("/account");
}

/**
 * Complete auth flow and navigate to account page.
 *
 * @param page - The Playwright page instance.
 */
export async function signInAndNavigateToAccount(page: Page): Promise<void> {
	await signInAsPrimary(page);
	await page.goto("/account");
	await page.waitForURL("/account");
}

