import { createConvexAuthHandlers } from '@mmailaender/convex-auth-svelte/sveltekit/server';

/**
 * Shared Convex Auth handlers singleton for SvelteKit request handling.
 *
 * Auto-detects convexUrl from PUBLIC_CONVEX_URL environment variable.
 * Export this instance to ensure consistent auth configuration across the app.
 *
 * @returns Configured Convex Auth handlers for SvelteKit hooks
 */
export const authHandlers = createConvexAuthHandlers();

import { ConvexCredentials } from '@convex-dev/auth/providers/ConvexCredentials';
import GitHub from '@auth/core/providers/github';
import { convexAuth } from '@convex-dev/auth/server';
import { internal } from './_generated/api';

/**
 * Convex authentication configuration with GitHub and test credentials.
 *
 * Exports auth methods for handling user authentication in the application.
 * Includes GitHub OAuth provider and a secret-based provider for E2E testing.
 *
 * @returns Object containing auth, signIn, signOut, store, and isAuthenticated functions
 */
export const { auth, signIn, signOut, store, isAuthenticated } = convexAuth({
	providers: [
		GitHub,
		ConvexCredentials({
			id: 'secret',
			authorize: async (params, ctx) => {
				const secret = [REDACTED];
				const primarySecret =
					[REDACTED] ?? process.env.AUTH_E2E_TEST_SECRET;
				const secondarySecret = [REDACTED];

				if (primarySecret && secret === primarySecret) {
					const user = await ctx.runQuery(internal.tests.getPrimaryTestUser);
					return { userId: user!._id };
				}

				if (secondarySecret && secret === secondarySecret) {
					const user = await ctx.runQuery(internal.tests.getSecondaryTestUser);
					return { userId: user!._id };
				}
				throw new Error('Invalid secret');
			}
		})
	]
});

import type { RequestHandler } from './$types';
import { authHandlers } from '#lib/server/convex-auth.ts';

const { isAuthenticated: isAuthenticatedPromise } = authHandlers;

/**
 * GET handler that returns authentication status.
 *
 * @param event - SvelteKit request event
 * @returns JSON response with authentication status and appropriate HTTP status code
 * @example
 * ```ts
 * // GET /api
 * // Response: { someData: true } with status 200 if authenticated
 * // Response: { someData: false } with status 403 if not authenticated
 * ```
 */
export const GET: RequestHandler = async (event) => {
	const isAuthenticated = await isAuthenticatedPromise(event);
	return Response.json({ someData: isAuthenticated }, { status: isAuthenticated ? 200 : 403 });
};

